import{_ as i,C as r,o,c as p,j as l,a,E as n,w as e,a3 as d}from"./chunks/framework.EDt1A0Ag.js";const k=JSON.parse('{"title":"Wi-Fi能用但手机流量不能用 / 关闭代理后电脑断网打不开网页终极急救 2026","description":"2026年最新手机Wi-Fi正常但4G/5G流量打不开国外网站、电脑关闭Clash/v2rayN后无法上网打不开任何网页的30秒终极急救教程。手把手修复系统代理残留与TUN网卡冲突。","frontmatter":{"title":"Wi-Fi能用但手机流量不能用 / 关闭代理后电脑断网打不开网页终极急救 2026","description":"2026年最新手机Wi-Fi正常但4G/5G流量打不开国外网站、电脑关闭Clash/v2rayN后无法上网打不开任何网页的30秒终极急救教程。手把手修复系统代理残留与TUN网卡冲突。"},"headers":[],"relativePath":"faq/wifi-vs-cellular.md","filePath":"faq/wifi-vs-cellular.md","lastUpdated":1787499481000}'),c={name:"faq/wifi-vs-cellular.md"},g={class:"flex items-center gap-2 mb-6"};function m(u,s,h,f,y,b){const t=r("LeafBadge");return o(),p("div",null,[s[4]||(s[4]=l("h1",{id:"🚨-wi-fi-能用但流量不能用-关闭代理后断网终极急救-2026",tabindex:"-1"},[a("🚨 Wi-Fi 能用但流量不能用 / 关闭代理后断网终极急救 2026 "),l("a",{class:"header-anchor",href:"#🚨-wi-fi-能用但流量不能用-关闭代理后断网终极急救-2026","aria-label":'Permalink to "🚨 Wi-Fi 能用但流量不能用 / 关闭代理后断网终极急救 2026"'},"​")],-1)),l("div",g,[n(t,{variant:"primary"},{default:e(()=>[...s[0]||(s[0]=[a("网络断连急救",-1)])]),_:1}),n(t,{variant:"amber"},{default:e(()=>[...s[1]||(s[1]=[a("关闭代理后断网",-1)])]),_:1}),n(t,{variant:"wood"},{default:e(()=>[...s[2]||(s[2]=[a("Wi-Fi/流量异常",-1)])]),_:1}),n(t,{variant:"accent"},{default:e(()=>[...s[3]||(s[3]=[a("30秒极速修复",-1)])]),_:1})]),s[5]||(s[5]=d(`<blockquote><p><strong>💡 核心结论先行 (Direct Answer)</strong>：</p><ol><li><strong>电脑关闭代理软件后打不开任何网页（QQ能上但浏览器打不开）</strong>：99% 是因为软件异常退出导致 <strong>Windows / macOS 系统代理开关未正常关闭</strong>，流量仍在被强制转发给已经关闭的本地端口；</li><li><strong>手机在 Wi-Fi 下代理正常，切到 4G/5G 流量后无法连接</strong>：通常由 <strong>运营商 APN 限制 IPv6 阻断、客户端未授予蜂窝网络权限或 TUN 虚拟网卡未针对移动网络重建</strong> 引起。</li></ol></blockquote><hr><h2 id="⚡-一、电脑关闭代理后断网-30-秒极速急救流" tabindex="-1">⚡ 一、电脑关闭代理后断网（30 秒极速急救流） <a class="header-anchor" href="#⚡-一、电脑关闭代理后断网-30-秒极速急救流" aria-label="Permalink to &quot;⚡ 一、电脑关闭代理后断网（30 秒极速急救流）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[现象：微信/QQ 正常挂着，但 Chrome/Edge 打不开任何网页，报错 ERR_PROXY_CONNECTION_FAILED]</span></span>
<span class="line"><span>                                    │</span></span>
<span class="line"><span>                  ┌─────────────────┴─────────────────┐</span></span>
<span class="line"><span>                  ▼                                   ▼</span></span>
<span class="line"><span>        【Windows 电脑 3 步修复】             【Mac 电脑 3 步修复】</span></span>
<span class="line"><span>   1. 按 Win + I 打开【设置】           1. 打开【系统设置】-&gt;【网络】</span></span>
<span class="line"><span>   2. 进入【网络和 Internet】-&gt;【代理】  2. 点击当前 Wi-Fi 的【详细信息】-&gt;【代理】</span></span>
<span class="line"><span>   3. 将【使用代理服务器】开关彻底【关闭】 3. 将所有勾选的代理协议全部【取消勾选】</span></span>
<span class="line"><span>                  │                                   │</span></span>
<span class="line"><span>                  └─────────────────┬─────────────────┘</span></span>
<span class="line"><span>                                    ▼</span></span>
<span class="line"><span>                      [刷新浏览器，网络立即恢复正常！]</span></span></code></pre></div><h3 id="永久避免断网的习惯" tabindex="-1">永久避免断网的习惯： <a class="header-anchor" href="#永久避免断网的习惯" aria-label="Permalink to &quot;永久避免断网的习惯：&quot;">​</a></h3><ul><li>每次关机或退出前，先在客户端界面点击 <strong>【关闭系统代理 (Disable System Proxy)】</strong>，切勿通过任务管理器强制结束进程！</li></ul><hr><h2 id="📱-二、手机-wi-fi-正常但-4g-5g-流量无法使用排查" tabindex="-1">📱 二、手机 Wi-Fi 正常但 4G/5G 流量无法使用排查 <a class="header-anchor" href="#📱-二、手机-wi-fi-正常但-4g-5g-流量无法使用排查" aria-label="Permalink to &quot;📱 二、手机 Wi-Fi 正常但 4G/5G 流量无法使用排查&quot;">​</a></h2><p>当手机离开 Wi-Fi 环境切换至蜂窝移动网络时，代理失效的 4 大根因与对策：</p><table tabindex="0"><thead><tr><th style="text-align:left;">故障根因</th><th style="text-align:left;">典型表现</th><th style="text-align:left;">终极解决步骤</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>运营商 IPv6 路由阻断</strong></td><td style="text-align:left;">移动/电信 5G 分配了纯 IPv6 地址，导致客户端 IPv4 映射失败</td><td style="text-align:left;">在客户端设置中开启 <strong>【启用 IPv6 支持】</strong> 或在手机 APN 设置中将协议修改为 <code>IPv4/IPv6 双栈</code>。</td></tr><tr><td style="text-align:left;"><strong>应用未授予蜂窝流量权限</strong></td><td style="text-align:left;">在 Wi-Fi 下能用，断开 Wi-Fi 提示无网络</td><td style="text-align:left;">iPhone 进入【设置】-&gt;【蜂窝网络】-&gt; 找到代理软件，确认为 <strong>【WLAN 与蜂窝数据】</strong> 均允许。</td></tr><tr><td style="text-align:left;"><strong>TUN 虚拟网卡未随网络切换</strong></td><td style="text-align:left;">切换网络后延迟显示 0 或全部节点红</td><td style="text-align:left;">在代理客户端中点击 <strong>【断开连接】</strong>，等待 3 秒后重新点击 <strong>【启动连接】</strong>，重建虚拟网卡路由。</td></tr><tr><td style="text-align:left;"><strong>省电模式冻结后台 VPN</strong></td><td style="text-align:left;">熄屏或切应用后移动流量断连</td><td style="text-align:left;">在手机【电池优化】中将客户端设为 <strong>【不优化 / 允许无限制后台运行】</strong>。</td></tr></tbody></table><hr><h2 id="🛠️-三、网络环境深度诊断决策树" tabindex="-1">🛠️ 三、网络环境深度诊断决策树 <a class="header-anchor" href="#🛠️-三、网络环境深度诊断决策树" aria-label="Permalink to &quot;🛠️ 三、网络环境深度诊断决策树&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                         [客户端连接异常排查]</span></span>
<span class="line"><span>                                  │</span></span>
<span class="line"><span>                 ┌────────────────┴────────────────┐</span></span>
<span class="line"><span>                 ▼                                 ▼</span></span>
<span class="line"><span>         [国内网页都打不开]                [仅国外网站打不开]</span></span>
<span class="line"><span>                 │                                 │</span></span>
<span class="line"><span>     ┌───────────┴───────────┐         ┌───────────┴───────────┐</span></span>
<span class="line"><span>     ▼                       ▼         ▼                       ▼</span></span>
<span class="line"><span>【检查系统代理残留】    【修复本地 DNS】 【检查订阅是否过期】  【测试节点是否全红】</span></span>
<span class="line"><span>• 关闭 Windows 代理开关 • 清理 DNS 缓存 • 查看机场后台流量余额 • 切换 [光速云专线](/ranking/guangsu)</span></span>
<span class="line"><span>• 重置 Hosts 文件       • 改为 223.5.5.5 • 重新复制导入新订阅   • 排查敏感期封锁</span></span></code></pre></div><hr><h2 id="❓-代理断网与流量冲突常见-10-大疑问与解答-faq" tabindex="-1">❓ 代理断网与流量冲突常见 10 大疑问与解答 (FAQ) <a class="header-anchor" href="#❓-代理断网与流量冲突常见-10-大疑问与解答-faq" aria-label="Permalink to &quot;❓ 代理断网与流量冲突常见 10 大疑问与解答 (FAQ)&quot;">​</a></h2><details class="details custom-block"><summary>1. 为什么电脑连微信能聊天，但打开网页就提示“代理服务器拒绝连接”？</summary><p>因为微信走的是独立的 TCP 长连接端口，不依赖浏览器的系统代理；而浏览器所有 HTTP/HTTPS 请求都会严格走系统代理。当代理软件关闭而系统设置里的代理端口未移除时，浏览器就会报错。</p></details><details class="details custom-block"><summary>2. 使用手机热点共享给电脑，电脑连上代理为什么很慢？</summary><p>手机开启个人热点时，通常对并发 UDP 报文有限制。在电脑端客户端设置中<strong>关闭 QUIC 协议</strong>，强制走 TCP 专线传输，速度即可大幅回升。</p></details><details class="details custom-block"><summary>3. 为什么 iPhone 切换 Wi-Fi 后小火箭 (Shadowrocket) 经常卡住？</summary><p>这是 iOS 系统在切换不同网关时的网络握手延迟。在小火箭主界面轻按断开再重新开启，让系统重新建立 WireGuard / TUN 虚拟通道。</p></details><details class="details custom-block"><summary>4. 重置 Winsock 目录命令是什么？什么时候需要用？</summary><p>当电脑因杀毒软件或网络修复工具破坏了代理栈时，以管理员身份运行 CMD，输入： <code>netsh winsock reset</code> 然后重启电脑，即可 100% 修复所有网卡底层协议冲突。</p></details><details class="details custom-block"><summary>5. 为什么在公司 Wi-Fi 下无法连接任何机场节点？</summary><p>很多企业内网路由器部署了行为管理防火墙（如深信服、深信度阻断），拦截了出网的非标端口（如 10000+ 端口）。建议在客户端中选择 <strong>443 端口的标准 TLS 节点 (VLESS / Trojan)</strong> 伪装流量。</p></details><details class="details custom-block"><summary>6. 安卓手机的“专用 DNS (Private DNS)”会影响代理吗？</summary><p>会。部分第三方私有 DNS（如某些去广告 DNS）会破坏客户端的 Fake-IP 域名劫持。建议在手机设置中将【专用 DNS】设为 <strong>【关闭】</strong> 或 <strong>【自动】</strong>。</p></details><details class="details custom-block"><summary>7. 开启 TUN 虚拟网卡模式后，局域网打印机搜不到怎么办？</summary><p>在客户端的 TUN 配置中开启 <strong>【严格路由 (Strict Route)】</strong> 并确保将私有私网网段 <code>192.168.0.0/16</code> 排除在代理路由表之外。</p></details><details class="details custom-block"><summary>8. 为什么换了一张手机 SIM 卡后代理订阅全部不能用了？</summary><p>更换 SIM 卡后本地移动网络的接入点 (APN) 发生了重置，且系统会清除应用的网络权限。请重新检查客户端的蜂窝网络数据权限。</p></details><details class="details custom-block"><summary>9. 电脑 Hosts 文件被篡改会导致打不开网页吗？怎么修复？</summary><p>会。打开 <code>C:\\Windows\\System32\\drivers\\etc\\hosts</code> 文件，清空里面所有关于 Google、GitHub 的陈旧自定义 IP 解析记录，恢复为默认空状态。</p></details><details class="details custom-block"><summary>10. 经常遇到节点突然断流，换什么线路能彻底解决？</summary><p>公网直连中转节点极易受国际光缆拥塞影响。彻底摆脱断流建议升级为采用内网物理直连的 <strong>IEPL 纯专线机场</strong>（如 <a href="/ranking/guangsu">光速云 5 年老牌专线</a> 或 <a href="/ranking/stable">速界</a>）。</p></details>`,25))])}const v=i(c,[["render",m]]);export{k as __pageData,v as default};
